// Assuming your text is coming from the previous node as 'content'
const inputText = $input.first().json.content.parts[0].text

// A simple way to handle potential markdown issues is to replace the characters
const safeText = inputText
  .replace(/\*/g, '\\*')  // Escape asterisks
  .replace(/_/g, '\\_')  // Escape underscores
  .replace(/\[/g, '\\[')  // Escape brackets
  .replace(/`/g, '\\`');  // Escape backticks

// Or, if you want to remove them altogether
// const safeText = inputText.replace(/[*_`]/g, '');

return {
  json: {
    safeText: safeText
  }
};
